try:
    from scipy.stats import beta, binom
except ImportError:
    print('scipy absent'); raise SystemExit
def kmax(n):
    k=-1
    for x in range(n+1):
        if beta.ppf(0.95, x+1, n-x) < 0.05: k=x
        else: break
    return k
for n in (200,300):
    k=kmax(n); p1=binom.cdf(k,n,0.01); p5=binom.cdf(k,n,0.05)
    print(n,'k max',k,'p(1%)',round(p1,4),'^3',round(p1**3,3),'^6',round(p1**6,3),'p(5%)',round(p5,4))
print('0.99^100', round(0.99**100,3), 'moyenne au-dessus a 300', 300*0.01)
EOF

